STOCK = {"laptop": 3, "monitor": 7, "dock": 4}


def _key(arg):
    k = arg.strip().strip('"\'').lower()
    if k.endswith("s") and k[:-1] in PRICES:
        k = k[:-1]
    return k


def price_of(arg):
