from common import (SYSTEM, RISKY, call_model, assistant_message,
                    tool_calls_of, run_tool)

def run(task, approve=lambda call: True, max_steps=6):
    messages = [{"role": "system", "content": SYSTEM},
                {"role": "user", "content": task}]
