    for _ in range(max_steps):
        msg, secs = call_model(messages)
        messages.append(assistant_message(msg))
        calls = tool_calls_of(msg)
        trace.append({"step": "model", "seconds": round(secs, 2),
                      "asked_for": [c["name"] for c in calls]})
